"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/agent-chat-input/variants/01-creative-composer";
import Variant1 from "./components/agent-chat-input/variants/02-pill-composer";
import Variant2 from "./components/agent-chat-input/variants/03-studio-composer";
import Variant3 from "./components/agent-chat-input/variants/04-credits-composer";
const variants = {
  "creative-composer": Variant0,
  "pill-composer": Variant1,
  "studio-composer": Variant2,
  "credits-composer": Variant3,
};
export interface ArtemisAgentChatInputProps {
  className?: string;
  variant?: "creative-composer" | "pill-composer" | "studio-composer" | "credits-composer";
}
export function ArtemisAgentChatInput({
  className,
  variant = "creative-composer",
}: ArtemisAgentChatInputProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}
